static redisAsyncContext * redisAsyncInitialize ( redisContext * c ) { redisAsyncContext * ac ; ac = realloc ( c , sizeof ( redisAsyncContext ) ) ; c = & ( ac -> c ) ; c -> flags &= ~ REDIS_CONNECTED ; ac -> err = 0 ; ac -> errstr = NULL ; ac -> data = NULL ; ac -> ev . data = NULL ; ac -> ev . addRead = NULL ; ac -> ev . delRead = NULL ; ac -> ev . addWrite = NULL ; ac -> ev . delWrite = NULL ; ac -> ev . cleanup = NULL ; ac -> onConnect = NULL ; ac -> onDisconnect = NULL ; ac -> replies . head = NULL ; ac -> replies . tail = NULL ; ac -> sub . invalid . head = NULL ; ac -> sub . invalid . tail = NULL ; ac -> sub . channels = dictCreate ( & callbackDict , NULL ) ; ac -> sub . patterns = dictCreate ( & callbackDict , NULL ) ; return ac ; } 